function Brand(){return <Link to="/" className="brand"><img src="/smartprep-logo.svg" alt="SmartPrep Axom logo" /> <span>SmartPrep <b>Axom</b></span></Link>}
function Header(){const [open,setOpen]=useState(false);const [intelOpen,setIntelOpen]=useState(true);const [workspaceOpen,setWorkspaceOpen]=useState(false);const [appOpen,setAppOpen]=useState(false);const [dark,setDark]=useState(false);const loc=useLocation();useEffect(()=>{const saved=localStorage.getItem("smartprep-theme");const initial=saved==="dark";setDark(initial);document.documentElement.dataset.theme=initial?"dark":"light";const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute("content",initial?"#101722":"#ffffff")},[]);const toggleTheme=()=>{setDark(v=>{const next=!v;document.documentElement.dataset.theme=next?"dark":"light";localStorage.setItem("smartprep-theme",next?"dark":"light");const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute("content",next?"#101722":"#ffffff");return next})};useEffect(()=>{setOpen(false);setIntelOpen(true);setWorkspaceOpen(false);setAppOpen(false)},[loc.pathname]);useEffect(()=>{if(!open)return;const previous=document.body.style.overflow;document.body.style.overflow="hidden";document.body.classList.add("nav-menu-open");const onKey=(e:KeyboardEvent)=>{if(e.key==="Escape")setOpen(false)};window.addEventListener("keydown",onKey);return()=>{document.body.style.overflow=previous;document.body.classList.remove("nav-menu-open");window.removeEventListener("keydown",onKey)}},[open]);const close=()=>setOpen(false);const intelligence=[["Intelligence dashboard","/analytics"],["Chapter-wise PYQ trends","/analytics/pyq-analysis"],["CEE Chapter Outlook","/cee-outlook"],["Exam difficulty","/analytics/exam-difficulty"],["CEE 2027 chapter prediction","/analytics/cee-2027-predictions"],["Marks-to-rank predictor","/predictor/rank"],["College predictor","/predictor/college"],["College cutoff explorer","/analytics/college-cutoff-analysis"],["CEE guide","/exam-guide"],["PYQ archive","/previous-papers"]];const workspace=[["Workspace home","/cee-tools"],["Daily 10","/daily-10"],["Chapter Intelligence","/chapter-intelligence"],["CEE Chapter Outlook","/cee-outlook"],["Admission Navigator","/admission-navigator"],["My College Path","/my-college-path"],["My CEE Journey","/my-cee-journey"],["My CEE Target Card","/my-target-card"]];const app=[["Download Android app","/app"],["All app features","/app/features"],["Practice library","/practice"],["Test series","/test-series"],["Plans & pricing","/pricing"],["About SmartPrep","/about"],["Reviews","/reviews"],["Community","/community"],["Contact & support","/contact"]];const group=(title:string,items:string[][],expanded:boolean,setExpanded:(v:boolean)=>void,kind:string)=><section className={"drawer-group drawer-"+kind+(expanded?" is-expanded":"")}><div className="drawer-group-head"><NavLink to={items[0][1]} onClick={close}>{title}</NavLink><button type="button" aria-label={"Toggle "+title+" links"} aria-expanded={expanded} onClick={()=>setExpanded(!expanded)}><ChevronDown size={18}/></button></div>{expanded&&<div className="drawer-links">{items.map(([label,path])=><NavLink key={path} to={path} onClick={close}>{label}<ArrowRight size={14}/></NavLink>)}</div>}</section>;return <><header className="header"><div className="nav-wrap"><Brand/><nav className="desktop-nav"><NavLink to="/" end>Home</NavLink><NavLink to="/analytics">Intelligence</NavLink><NavLink to="/cee-tools">CEE Workspace</NavLink><NavLink to="/app">App</NavLink></nav><button className={"menu-btn"+(open?" is-open":"")} onClick={()=>setOpen(v=>!v)} aria-label={open?"Close navigation":"Open navigation"} aria-expanded={open}>{open?<X/>:<Menu/>}</button></div></header>{open&&<><button className="drawer-backdrop" aria-label="Close navigation menu" onClick={close}/><aside className="mobile-drawer" role="dialog" aria-modal="true" aria-label="Main navigation"><div className="drawer-top"><Brand/><button type="button" onClick={close} aria-label="Close menu"><X/></button></div><NavLink className="drawer-home" to="/" onClick={close}>Home <ArrowRight size={16}/></NavLink>{group("CEE Intelligence",intelligence,intelOpen,setIntelOpen,"intelligence")}{group("CEE Workspace",workspace,workspaceOpen,setWorkspaceOpen,"workspace")}{group("App",app,appOpen,setAppOpen,"app")}<div className="drawer-bottom"><button className="drawer-theme" type="button" onClick={toggleTheme}>{dark?<Sun size={17}/>:<Moon size={17}/>} {dark?"Light appearance":"Dark appearance"}</button><span>Prepare Smarter. Perform Better.</span></div></aside></>}<button className="theme-toggle" type="button" onClick={toggleTheme} aria-label={dark?"Switch to light mode":"Switch to dark mode"} title={dark?"Light mode":"Dark mode"}>{dark?<Sun size={19}/>:<Moon size={19}/>}</button></>}
function Footer(){return <footer className="footer"><div className="container footer-grid"><div><Brand/><p>Structured preparation resources for Assam CEE 2027.</p><small>Prepare Smarter. Perform Better.</small></div><div><h4>Explore</h4>{[["CEE Intelligence","/analytics"],["College predictor","/predictor/college"],["CEE Workspace","/cee-tools"],["My CEE Target Card","/my-target-card"],["PYQ archive","/previous-papers"],["CEE guide","/exam-guide"],["Download app","/app"],["Explore app features","/app/features"]].map(([n,p])=><Link key={p} to={p}>{n}</Link>)}</div><div><h4>Subjects</h4>{subjects.map(s=><Link key={s.path} to={s.path}>{s.name}</Link>)}</div><div><h4>Policies &amp; links</h4>{[["FAQ","/faq"],["Contact","/contact"],["Privacy","/privacy-policy"],["Terms","/terms-and-conditions"],["Refunds","/refund-policy"],["Disclaimer","/disclaimer"],["Copyright","/copyright"]].map(([n,p])=><Link key={p} to={p}>{n}</Link>)}</div></div><div className="container footer-bottom">© {new Date().getFullYear()} SmartPrep Axom. All rights reserved. <span>Independent educational preparation platform.</span></div></footer>}
